-- +goose Up
-- +goose StatementBegin

-- Point every purchasable row at the LIVE LemonSqueezy store (432789).
--
-- The rows already carry TEST-mode variant ids from the pre-launch store; those
-- ids do not exist in the live store, so leaving them would make checkout fail
-- and — worse — make `order_created` / `subscription_created` webhooks arrive
-- with a variant no row matches, which is how a customer pays and gets nothing
-- (see GetPlanByVariant in billing/payments/service.go).
--
-- Ids retrieved from GET /v1/variants?include=product and generated by
-- server/scripts/ls_variants.py, rather than transcribed by hand — a mistyped
-- variant id does not fail loudly, it silently sells the wrong plan.
--
-- Prices below are the live-store prices; each matches the price_cents already
-- seeded for that row (migrations 00025–00027), which is the check that the
-- mapping is right.
--
-- NOTE: these ids are specific to the live store. If a separate staging
-- database is ever stood up, it will pick this migration up too and inherit
-- live payment identifiers — at which point this should become an environment
-- -scoped seed instead. Today there is a single database, so a migration is
-- the right place for it.

-- Subscriptions. NB: each product also has an auto-created "Default" variant
-- with status=pending carrying the SAME price — those are not purchasable and
-- are deliberately not used here.
UPDATE plans SET lemonsqueezy_variant_id = '1974773' WHERE id = 'pro-monthly';    -- Dragent Pro / Monthly              $20.00
UPDATE plans SET lemonsqueezy_variant_id = '1974785' WHERE id = 'pro-annual';     -- Dragent Pro / Annual (Save 10%)    $216.00
UPDATE plans SET lemonsqueezy_variant_id = '1974793' WHERE id = 'max-monthly';    -- Dragent Max / Monthly              $60.00
UPDATE plans SET lemonsqueezy_variant_id = '1974797' WHERE id = 'max-annual';     -- Dragent Max / Annual (Save 10%)    $648.00
UPDATE plans SET lemonsqueezy_variant_id = '1974804' WHERE id = 'ultra-monthly';  -- Dragent Ultra / Monthly            $200.00
UPDATE plans SET lemonsqueezy_variant_id = '1974810' WHERE id = 'ultra-annual';   -- Dragent Ultra / Annual (Save 10%)  $2,160.00

-- One-time credit packs (all variants of the single "Dragent credits" product).
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974664' WHERE id = 'pack-10';    -- $10 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974623' WHERE id = 'pack-20';    -- $20 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974656' WHERE id = 'pack-50';    -- $50 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974635' WHERE id = 'pack-100';   -- $100 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974638' WHERE id = 'pack-200';   -- $200 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974650' WHERE id = 'pack-500';   -- $500 credits
UPDATE credit_packs SET lemonsqueezy_variant_id = '1974655' WHERE id = 'pack-1000';  -- $1000 credits

-- The live store has no $5 variant (smallest is $10). Deactivate rather than
-- leave a purchasable row that cannot check out; every plan and pack lookup
-- filters on is_active, so this makes it cleanly invisible.
UPDATE credit_packs SET is_active = FALSE, lemonsqueezy_variant_id = '' WHERE id = 'pack-5';

-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin

-- Blank the ids rather than restore the test-mode ones: those belong to a
-- different store and re-introducing them would point live checkout at products
-- that do not exist. A blank id makes Checkout refuse outright ("plan has no
-- variant id configured"), which is the safe direction to fail.
UPDATE plans SET lemonsqueezy_variant_id = ''
 WHERE id IN ('pro-monthly', 'pro-annual', 'max-monthly', 'max-annual', 'ultra-monthly', 'ultra-annual');

UPDATE credit_packs SET lemonsqueezy_variant_id = ''
 WHERE id IN ('pack-10', 'pack-20', 'pack-50', 'pack-100', 'pack-200', 'pack-500', 'pack-1000');

UPDATE credit_packs SET is_active = TRUE WHERE id = 'pack-5';

-- +goose StatementEnd
